// The catalog build and the AI context pack (CATALOG_SPEC 6-7, 11): the committed generated files are
// current, the pack stays within budget and mentions everything a model may use, and its examples validate.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { readCatalogDir, engineCodes, CATALOG_DIR } from "../../tools/lib/catalog_files.mjs";
import { buildCatalog, engineVocab, GENERATED_NOTE } from "../../tools/lib/catalog_build.mjs";
import { PACK_FILES, WORLD_GROUPS } from "../../tools/lib/context_pack.mjs";
import { crc32, zip } from "../../tools/lib/zip.mjs";
import { validate } from "../../engine/index.js";
import { WORLD_COMMANDS_V2 } from "../../engine/validator/semantic.js";
import { MACRO_PARAMS } from "../../engine/validator/macro_params.js";
import { isWorkbookCode } from "../../tools/lib/story_tables.mjs";

const SRC = readCatalogDir();
const codes = engineCodes();
const built = buildCatalog(SRC, { codes });
const pack = (f) => built.files[`generated/context/${f}`];
const all = () => Object.keys(PACK_FILES).map(pack).join("\n");

test("the build passes its checks", () => assert.deepEqual(built.issues, []));

test("committed generated files are current (run npm run catalog:build)", () => {
  for (const [rel, text] of Object.entries(built.files)) {
    let committed = null;
    try {
      committed = readFileSync(join(CATALOG_DIR, rel), "utf8");
    } catch {}
    assert.ok(committed === text, `${rel} is stale: run npm run catalog:build`);
  }
});

test("the build is deterministic and marks its files as generated", () => {
  assert.deepEqual(buildCatalog(readCatalogDir(), { codes }).files, built.files);
  for (const [rel, text] of Object.entries(built.files)) {
    if (rel.endsWith(".json")) assert.equal(JSON.parse(text)._generated, GENERATED_NOTE, rel);
    else if (!rel.endsWith("project_instructions.md")) assert.match(text, /^<!-- generated by npm run catalog:build; do not edit -->/, rel);
  }
});

test("pack: each file within its budget (+25%), the whole pack under 100 KB, the core tier under 62 KB", () => {
  let total = 0;
  let core = 0;
  for (const [f, m] of Object.entries(PACK_FILES)) {
    const bytes = Buffer.byteLength(pack(f));
    assert.ok(bytes <= m.budget * 1.25, `${f}: ${bytes} B, budget ${m.budget} B`);
    total += bytes;
    if (m.tier === "core") core += bytes;
  }
  assert.ok(total < 100000, `pack ${total} B`);
  assert.ok(core < 62000, `core ${core} B`);
});

test("pack: mentions every move, theme, object, prop, face, body, fx, activity, mood, macro, world command, code and preset", () => {
  const text = all();
  const c = SRC.catalog;
  const groups = {
    moves: c.moves.filter((m) => !m.flags?.partner).map((m) => m.name), themes: c.themeNames, objects: Object.keys(c.objects), props: Object.keys(c.props),
    faces: c.faceNames, bodies: c.bodyNames, fx: c.fxNames, activities: c.activityNames, moods: Object.keys(c.musicMoods),
    macros: Object.keys(MACRO_PARAMS).map((m) => `@${m}`), world: Object.keys(WORLD_COMMANDS_V2), codes: [...codes].filter((c) => !isWorkbookCode(c)), presets: SRC.presets.map((p) => p.id),
  };
  for (const [g, names] of Object.entries(groups)) for (const n of names) assert.ok(new RegExp(`(^|[^a-z_])${n}([^a-z_]|$)`, "m").test(text), `${g}: ${n} is not in the pack`);
});

test("pack: each world command is listed in exactly one file", () => {
  for (const n of Object.keys(WORLD_COMMANDS_V2)) {
    const row = new RegExp(`^\\| ${n} \\| [^|]+ \\| [^|]+ \\|$`, "m"); // a three-column world command row
    const where = Object.keys(PACK_FILES).filter((f) => row.test(pack(f)));
    assert.equal(where.length, 1, `${n}: ${where.join(", ")}`);
  }
  assert.ok(Object.values(WORLD_GROUPS).flat().every((n) => n in WORLD_COMMANDS_V2));
});

test("pack: the example clip validates and the example scenes are taken verbatim from validated stories", () => {
  const blocks = [...pack("08_examples.md").matchAll(/```json\n([\s\S]*?)\n```/g)].map((m) => JSON.parse(m[1]));
  assert.equal(blocks.length, 7); // a clip, an outline, five scenes
  assert.deepEqual(validate(blocks[0], SRC.catalog).errors, []);
  const scenes = Object.values(SRC.examples).filter((e) => e.story).flatMap((e) => e.story.scenes);
  for (const s of blocks.slice(2)) assert.ok(scenes.some((x) => JSON.stringify(x) === JSON.stringify(s)), s.id);
});

test("pack: the version stamp is in the start file, the instructions and the manifest", () => {
  const manifest = JSON.parse(built.files["manifest.json"]);
  assert.match(built.version, /^1-[0-9a-f]{10}$/);
  assert.equal(manifest.version, built.version);
  assert.ok(pack("00_start_here.md").includes(`Catalog version ${built.version}`));
  assert.ok(pack("project_instructions.md").includes(`Catalog version ${built.version}`));
  assert.ok(manifest.authored.includes("moves/poses.json") && !manifest.authored.some((f) => f.startsWith("generated/")));
});

test("engine vocabulary: world commands, macros, enums, limits and codes come from the engine", () => {
  const v = JSON.parse(built.files["generated/engine_vocab.json"]);
  assert.deepEqual(Object.keys(v.worldCommands), Object.keys(WORLD_COMMANDS_V2));
  assert.deepEqual(Object.keys(v.macroParams), Object.keys(MACRO_PARAMS));
  assert.deepEqual(v.codes, [...codes].sort());
  assert.deepEqual(v.voice, { pitch: [0.5, 2], speed: [0.7, 1.4], timbre: ["soft", "squeaky", "deep", "robot", "bark"] });
  assert.equal(v.worldCommands.narrate.v1, false);
  assert.equal(v.worldCommands.shake.v1, true);
  assert.deepEqual(JSON.parse(JSON.stringify(engineVocab(codes))), v);
});

test("the full catalog file carries descriptions, presets with their good themes, docs and example facts", () => {
  const full = JSON.parse(built.files["generated/catalog.json"]);
  assert.equal(full.catalog.moves.find((m) => m.name === "hug").description, SRC.catalog.moves.find((m) => m.name === "hug").description);
  assert.ok(full.presets.find((p) => p.id === "kai").goodThemes.includes("city_park"));
  assert.ok(full.docs.codes.E_SIM_UNREACHABLE.fix);
  const brave = full.examples.find((e) => e.path === "stories/brave_heart.json");
  assert.ok(brave.seconds > 100 && brave.macros.includes("fight"));
});

test("zip: crc32 and a well-formed archive", () => {
  assert.equal(crc32(Buffer.from("123456789")), 0xcbf43926);
  const z = zip([{ name: "a.md", data: "hello" }, { name: "b.md", data: "world" }]);
  assert.equal(z.readUInt32LE(0), 0x04034b50);
  assert.equal(z.readUInt32LE(z.length - 22), 0x06054b50);
  assert.equal(z.readUInt16LE(z.length - 22 + 10), 2);
  assert.deepEqual(zip([{ name: "a.md", data: "hello" }]), zip([{ name: "a.md", data: "hello" }]));
});
